/* Page renderers. Every displayed task links to a real curriculum record and persisted state. */
(function () {
  'use strict';
  const LM = window.LM;
  const Store = window.LMStore;
  const UI = window.LMUI;
  const esc = UI.esc;
  const icon = UI.icon;

  function queryParam(name) { return new URLSearchParams(window.location.search).get(name); }
  function activeStatusCounts(projectId) {
    const curriculum = LM.curricula[projectId];
    const counts = { total: curriculum.tasks.length, completed: 0, in_progress: 0, blocked: 0, not_started: 0, actionable: 0 };
    curriculum.tasks.forEach(task => {
      const status = Store.statusOf(task.id);
      counts[status] += 1;
      if (status !== 'completed' && status !== 'blocked' && Store.dependenciesComplete(task.id)) counts.actionable += 1;
    });
    return counts;
  }
  function projectsGrid(options) {
    const settings = options || {};
    return '<div class="project-grid' + (settings.compact ? ' compact' : '') + '">' + LM.projects.map(project => {
      const p = Store.progress(project.id);
      const meta = Store.get().projects[project.id];
      const active = meta.startedAt && !meta.completedAt;
      return '<article class="project-card" data-project-card data-project-name="' + esc((project.title + ' ' + project.category + ' ' + project.tagline).toLowerCase()) + '" data-project-number="' + project.number + '" data-project-progress="' + p.percent + '">' +
        '<div class="pc-art pc-art-' + project.number + '"><span class="pc-art-grid"></span><span class="pc-number">PROJECT ' + String(project.number).padStart(2, '0') + '</span><span class="pc-icon">' + icon(['building','bag-heart','layers','mortarboard','people','kanban','calendar2-check','headset','file-earmark-check','share'][project.number - 1]) + '</span><span class="pc-art-category">' + esc(project.category) + '</span></div>' +
        '<div class="pc-body"><div class="pc-top"><h3><a href="' + UI.projectUrl(project.id) + '">' + esc(project.title) + '</a></h3>' + UI.projectStatusBadge(project.id) + '</div>' +
        '<p>' + esc(project.tagline) + '</p>' +
        '<div class="project-tags"><span>' + icon('diagram-3') + ' ' + project.modules.length + ' modules</span><span>' + icon('list-check') + ' ' + p.total + ' steps</span><span>' + icon('clock') + ' ' + esc(project.effort) + '</span></div>' +
        '<div class="project-progress"><div><span>Mandatory progress</span><strong>' + p.percent + '%</strong></div>' + UI.progressBar(p.percent, project.title + ' progress') + '<small>' + p.completed + ' of ' + p.total + ' steps complete' + (p.blocked ? ' · ' + p.blocked + ' blocked' : '') + '</small></div>' +
        '<div class="project-card-actions"><a class="btn btn-outline btn-sm" href="' + UI.projectUrl(project.id) + '">Overview</a><a class="btn btn-quiet btn-sm" href="' + UI.roadmapUrl(project.id) + '">' + (active ? 'Continue' : 'Roadmap') + ' ' + icon('arrow-right') + '</a></div></div>' +
        '</article>';
    }).join('') + '</div>';
  }
  function activityList(items, emptyMessage) {
    if (!items.length) return '<div class="empty-inline">' + icon('clock-history') + '<span>' + esc(emptyMessage || 'No activity recorded yet.') + '</span></div>';
    return '<ul class="activity-list">' + items.map(item => {
      const iconName = { complete: 'check2-circle', start: 'play-circle', block: 'pause-circle', unblock: 'play-circle', reopen: 'arrow-counterclockwise', git: 'git', project: 'folder2-open', 'project-complete': 'patch-check', 'project-reopen': 'arrow-counterclockwise', import: 'upload', reset: 'trash3', 'reset-project': 'trash3', export: 'download' }[item.type] || 'activity';
      const task = item.taskId && LM.taskIndex[item.taskId];
      return '<li class="activity-item"><span class="activity-icon">' + icon(iconName) + '</span><div><p>' + esc(item.message) + '</p><small>' + esc(LM.taskIndex[item.taskId] ? LM.taskIndex[item.taskId].projectId.toUpperCase() : item.projectId.toUpperCase()) + ' · ' + esc(UI.formatDate(item.at)) + (task ? ' · <a href="' + UI.taskUrl(task.id) + '">Open task</a>' : '') + '</small></div></li>';
    }).join('') + '</ul>';
  }
  function nextTaskCard(projectId) {
    const target = Store.continueTarget();
    const project = LM.projects.find(item => item.id === projectId) || LM.projects[0];
    if (target.reason === 'complete') {
      return '<div class="next-card complete"><div class="next-icon">' + icon('patch-check') + '</div><div><p class="eyebrow">Project complete</p><h3>All mandatory steps are complete</h3><p>Review the final report and project gate.</p></div><a class="btn btn-outline btn-sm" href="' + UI.projectUrl(project.id) + '">Final report</a></div>';
    }
    if (!target.task) {
      return '<div class="next-card blocked"><div class="next-icon">' + icon('pause-octagon') + '</div><div><p class="eyebrow">Blocked chain</p><h3>No unblocked task can be recommended</h3><p>Resolve a blocked task in this project or work on another project. Completed progress is preserved.</p></div><a class="btn btn-outline btn-sm" href="' + UI.roadmapUrl(project.id, 'status=blocked') + '">View blockers</a></div>';
    }
    return '<div class="next-card"><div class="next-icon">' + icon(target.blocked ? 'pause-circle' : 'compass') + '</div><div><p class="eyebrow">' + (target.blocked ? 'Resume blocked task' : 'Recommended next step') + '</p><h3>' + esc(target.task.title) + '</h3><p>' + esc(target.task.module) + ' · Phase ' + target.task.phase + ' · ' + esc('~' + UI.effortLabel(target.task.effort)) + '</p><p class="next-reason">' + (target.blocked ? 'This task is blocked. Record or resolve the blocker; do not skip it.' : 'Selected because every prerequisite is complete, the task is not blocked, and it is the earliest incomplete mandatory step in this project.') + '</p></div><a class="btn btn-accent btn-sm" href="' + UI.taskUrl(target.task.id) + '">' + icon('arrow-right') + ' Open task</a></div>';
  }

  function renderDashboard(query) {
    const global = Store.globalProgress();
    const state = Store.get();
    const currentTask = state.activeTaskId && LM.taskIndex[state.activeTaskId];
    const target = Store.continueTarget();
    const project = LM.projects.find(item => item.id === state.activeProjectId) || LM.projects[0];
    const projectProgress = Store.progress(project.id);
    const completedTasks = Object.entries(state.tasks).filter(([, record]) => record.completedAt).map(([id, record]) => ({ id, record })).sort((a, b) => String(b.record.completedAt).localeCompare(String(a.record.completedAt)));
    const lastCompleted = completedTasks[0] ? LM.taskIndex[completedTasks[0].id] : null;
    const blockedEntries = Object.entries(state.tasks).filter(([, record]) => record.blockedReason && !record.completedAt);
    const bookmarks = state.bookmarks.map(id => LM.taskIndex[id]).filter(Boolean).slice(0, 5);
    const phases = Store.phaseProgress(project.id);
    const topProjects = [...global.projects].sort((a, b) => b.percent - a.percent).slice(0, 4);
    const isFresh = global.completed === 0;
    const currentPhase = currentTask ? currentTask.phase : (phases.find(item => item.completed < item.total) || phases[0]).phase.id;
    return '' +
      '<section class="hero-dashboard">' +
        '<div class="hero-grid" aria-hidden="true"></div><div class="hero-glow" aria-hidden="true"></div>' +
        '<div class="hero-copy-block"><p class="hero-eyebrow"><span class="hero-pulse"></span> Laravel 12 · Independent engineering track</p>' +
        '<h1>Build ten <em>production-minded</em> Laravel applications.</h1>' +
        '<p class="hero-lede">A dependency-aware curriculum that takes you from environment setup to authentication, domain modules, advanced engineering, testing, security and a documented release. Every step is small, verifiable and yours to complete.</p>' +
        '<div class="hero-cta"><a class="btn btn-hero" id="continue" href="' + (target.task ? UI.taskUrl(target.task.id) : UI.projectUrl(project.id)) + '">' + icon('play-fill') + ' Continue learning</a><a class="btn btn-ghost-hero" href="projects.html">' + icon('grid') + ' Explore the 10 projects</a></div>' +
        '<div class="hero-stats"><span><strong>' + global.total.toLocaleString('en-US') + '</strong> micro-steps</span><span><strong>10</strong> projects</span><span><strong>100</strong> modules</span><span><strong>100</strong> advanced features</span></div></div>' +
        '<div class="hero-panel"><div class="hero-panel-head"><span>' + icon('activity') + ' Your workspace</span>' + UI.projectStatusBadge(project.id) + '</div>' +
          '<div class="hero-ring-row"><div class="hero-ring" style="--percent:' + projectProgress.percent + '"><span>' + projectProgress.percent + '%</span></div><div class="hero-ring-facts"><span>Active project</span><strong>' + esc(project.title) + '</strong><small>' + esc('Phase ' + currentPhase + ' · ' + (currentTask ? currentTask.module : 'Not started')) + '</small></div></div>' +
          '<div class="hero-mini-progress">' + phases.slice(0, 5).map(item => '<div><span>' + item.phase.id + '</span>' + UI.progressBar(item.total ? Math.round(item.completed / item.total * 100) : 0, item.phase.short) + '</div>').join('') + '</div>' +
          '<div class="hero-panel-foot"><span>' + icon('check2-circle') + ' ' + global.completed.toLocaleString('en-US') + ' completed</span><span>' + icon('pause-circle') + ' ' + global.blocked + ' blocked</span><a href="progress.html">Details ' + icon('arrow-right') + '</a></div>' +
        '</div>' +
      '</section>' +
      (isFresh ? '<div class="start-banner">' + icon('signpost-split') + '<div><strong>Start with Project 01, then follow each task’s prerequisites.</strong><p>All ten projects are open from day one. Progress is calculated only from completed mandatory steps and saved in this browser.</p></div><a href="' + UI.taskUrl(LM.projects[0].id + '-plan-purpose') + '" class="btn btn-outline btn-sm">Open first task ' + icon('arrow-right') + '</a></div>' : '') +
      '<div class="metric-grid"><article class="metric-card"><div class="metric-top"><span class="metric-icon red">' + icon('check2-circle') + '</span><span class="metric-trend">' + (global.total ? Math.round(global.completed / global.total * 100) : 0) + '%</span></div><strong>' + global.completed.toLocaleString('en-US') + '</strong><span class="metric-label">Completed micro-steps</span><div class="metric-foot">of ' + global.total.toLocaleString('en-US') + ' mandatory</div></article><article class="metric-card"><div class="metric-top"><span class="metric-icon blue">' + icon('pie-chart') + '</span><span class="metric-trend">' + global.completedProjects + '/10</span></div><strong>' + global.percent + '%</strong><span class="metric-label">Overall completion</span>' + UI.progressBar(global.percent, 'Overall completion') + '</article><article class="metric-card"><div class="metric-top"><span class="metric-icon green">' + icon('folder2-open') + '</span><span class="metric-trend">' + global.inProgressProjects + ' active</span></div><strong>' + global.completedProjects + '</strong><span class="metric-label">Projects completed</span><div class="metric-foot">' + global.notStartedProjects + ' not started</div></article><article class="metric-card"><div class="metric-top"><span class="metric-icon amber">' + icon('pause-circle') + '</span><span class="metric-trend">' + state.bookmarks.length + ' saved</span></div><strong>' + global.blocked + '</strong><span class="metric-label">Blocked micro-steps</span><div class="metric-foot">' + global.remaining.toLocaleString('en-US') + ' steps remaining</div></article></div>' +
      '<section class="panel task-finder"><div class="finder-head"><div><h3>' + icon('search') + ' Find your next exact action</h3><p>Search 3,460 micro-steps by title, module or action. Filter by phase and status on the roadmap.</p></div><form class="finder-bar" method="get" action="roadmap.html"><label><span class="visually-hidden">Project</span><select name="project" aria-label="Project">' + LM.projects.map(item => '<option value="' + item.id + '"' + (item.id === project.id ? ' selected' : '') + '>P' + String(item.number).padStart(2, '0') + ' — ' + esc(item.title) + '</option>').join('') + '</select></label><label><span class="visually-hidden">Task search</span><input type="search" name="q" placeholder="Search task, module or action…"></label><label><span class="visually-hidden">Phase</span><select name="phase" aria-label="Phase"><option value="">All phases</option>' + LM.phases.map(phase => '<option value="' + phase.id + '">' + phase.id + '. ' + esc(phase.name) + '</option>').join('') + '</select></label><label><span class="visually-hidden">Status</span><select name="status" aria-label="Status"><option value="all">All statuses</option><option value="actionable">Actionable now</option><option value="not_started">Not started</option><option value="in_progress">In progress</option><option value="blocked">Blocked</option><option value="completed">Completed</option></select></label><button class="btn btn-accent" type="submit">' + icon('search') + ' Find</button></form></div></section>' +
      '<div class="section-head section-head-spaced"><div><h2>Continue where you left off</h2><p>Your active project, current task and the next dependency-safe step.</p></div><div class="library-controls"><label class="inline-picker"><span>Active project</span><select data-project-picker aria-label="Choose active project">' + LM.projects.map(item => '<option value="' + item.id + '"' + (item.id === project.id ? ' selected' : '') + '>P' + String(item.number).padStart(2, '0') + ' — ' + esc(item.title) + '</option>').join('') + '</select></label></div></div>' +
      '<div class="dashboard-grid">' +
      '<section class="panel panel-active"><div class="panel-head"><div><p class="eyebrow">Active project</p><h2>' + esc(project.title) + '</h2></div>' + UI.projectStatusBadge(project.id) + '</div>' +
      '<div class="active-summary"><div class="active-progress-ring" style="--percent:' + projectProgress.percent + '"><span>' + projectProgress.percent + '%</span><small>complete</small></div><div class="active-facts"><div><span>Phase</span><strong>' + esc(currentTask ? currentTask.phaseName : 'Not started') + '</strong></div><div><span>Module</span><strong>' + esc(currentTask ? currentTask.module : '—') + '</strong></div><div><span>Current task</span><strong>' + esc(currentTask ? currentTask.title : 'No task started') + '</strong></div><div><span>Last completed</span><strong>' + esc(lastCompleted ? lastCompleted.title : 'None yet') + '</strong></div></div></div>' +
      '<div class="files-in-focus"><span>Files in focus</span><code>' + esc(currentTask ? currentTask.files : 'Select or start a task to see its file paths.') + '</code></div>' +
      '<div class="active-phase-list">' + phases.map(item => '<div class="phase-mini"><div class="phase-mini-label"><span>' + item.phase.id + '. ' + esc(item.phase.name) + '</span><strong>' + item.completed + '/' + item.total + '</strong></div>' + UI.progressBar(item.total ? Math.round(item.completed / item.total * 100) : 0, item.phase.name + ' progress') + '</div>').join('') + '</div>' +
      '<div class="panel-actions"><a class="btn btn-outline btn-sm" href="' + UI.projectUrl(project.id) + '">Project overview</a><a class="btn btn-quiet btn-sm" href="' + UI.roadmapUrl(project.id) + '">Full roadmap ' + icon('arrow-right') + '</a></div></section>' +
      '<div class="dashboard-side">' + nextTaskCard(project.id) +
      '<section class="panel"><div class="panel-head"><h2>Training status</h2><a class="text-link" href="progress.html">Details ' + icon('arrow-right') + '</a></div><div class="stat-rows"><div><span>Projects completed</span><strong>' + global.completedProjects + '</strong></div><div><span>Projects in progress</span><strong>' + global.inProgressProjects + '</strong></div><div><span>Projects not started</span><strong>' + global.notStartedProjects + '</strong></div><div><span>Remaining micro-steps</span><strong>' + global.remaining.toLocaleString('en-US') + '</strong></div><div><span>Blocked / bookmarked</span><strong>' + global.blocked + ' / ' + state.bookmarks.length + '</strong></div></div></section>' +
      '<section class="panel"><div class="panel-head"><h2>Recently completed</h2></div>' + activityList(state.activity.filter(item => item.type === 'complete').slice(0, 4), 'Completed tasks will appear here.') + '</section></div></div>' +
      '<section class="library-section" id="project-library"><div class="section-head"><div><h2>Your project library</h2><p>Ten independent products, each with its own repository, database, tests and release gate.</p></div><div class="library-controls"><label class="mini-search">' + icon('search') + '<span class="visually-hidden">Filter project cards</span><input type="search" placeholder="Filter projects" data-project-filter id="project-filter"></label><select class="form-select form-select-sm" data-project-sort id="project-sort" aria-label="Sort project cards"><option value="number">Project number</option><option value="progress">Progress</option><option value="name">Name</option></select></div></div>' +
      projectsGrid() + '</section>' +
      '<div class="dashboard-three"><section class="panel"><div class="panel-head"><h2>' + icon('pause-circle') + ' Blocked work</h2><a class="text-link" href="progress.html#blocked">View all</a></div>' + (blockedEntries.length ? '<ul class="compact-task-list">' + blockedEntries.slice(0, 4).map(([id]) => { const task = LM.taskIndex[id]; return '<li><span class="status-pill status-blocked"><span class="status-dot"></span>Blocked</span><div><a href="' + UI.taskUrl(id) + '">' + esc(task.title) + '</a><small>' + esc(task.projectId.toUpperCase()) + ' · ' + esc(task.module) + '</small></div></li>'; }).join('') + '</ul>' : '<div class="empty-inline">' + icon('check2') + '<span>No blocked tasks. Record a blocker whenever you pause so you can resume safely.</span></div>') + '</section>' +
      '<section class="panel"><div class="panel-head"><h2>' + icon('bookmark-star') + ' Bookmarks</h2></div>' + (bookmarks.length ? '<ul class="compact-task-list">' + bookmarks.map(task => '<li><span class="activity-icon">' + icon('bookmark') + '</span><div><a href="' + UI.taskUrl(task.id) + '">' + esc(task.title) + '</a><small>' + esc(task.projectId.toUpperCase()) + ' · ' + esc(task.module) + '</small></div></li>').join('') + '</ul>' : '<div class="empty-inline">' + icon('bookmark') + '<span>Bookmark a task to keep it close.</span></div>') + '</section>' +
      '<section class="panel"><div class="panel-head"><h2>' + icon('trophy') + ' Leading progress</h2></div><div class="stat-rows">' + topProjects.map(item => '<div class="leading-row"><span><strong>' + esc(item.project.title) + '</strong><small>' + item.completed + '/' + item.total + ' steps</small></span><span class="leading-percent">' + item.percent + '%</span></div>').join('') + '</div></section></div>' +
      '<section class="panel activity-panel"><div class="panel-head"><h2>Recent activity</h2><a class="text-link" href="progress.html">Full activity ' + icon('arrow-right') + '</a></div>' + activityList(state.activity.slice(0, 8), 'Start a task to create your first activity record.') + '</section>';
  }

  function renderProjects(query) {
    const q = (query.q || '').toLowerCase().trim();
    const status = query.status || 'all';
    const category = query.category || 'all';
    const sort = query.sort || 'number';
    const categories = [...new Set(LM.projects.map(project => project.category))];
    let projects = LM.projects.filter(project => {
      const p = Store.progress(project.id);
      const meta = Store.get().projects[project.id];
      const projectStatus = meta.completedAt ? 'completed' : p.blocked ? 'blocked' : p.completed ? 'in_progress' : 'not_started';
      const matchesQuery = !q || (project.title + ' ' + project.category + ' ' + project.tagline + ' ' + project.purpose).toLowerCase().includes(q);
      const matchesStatus = status === 'all' || status === projectStatus;
      const matchesCategory = category === 'all' || project.category === category;
      return matchesQuery && matchesStatus && matchesCategory;
    });
    if (sort === 'progress') projects = projects.slice().sort((a, b) => Store.progress(b.id).percent - Store.progress(a.id).percent);
    else if (sort === 'name') projects = projects.slice().sort((a, b) => a.title.localeCompare(b.title));
    const taskMatches = q ? Object.values(LM.taskIndex).filter(task => (task.title + ' ' + task.module + ' ' + task.objective).toLowerCase().includes(q)).slice(0, 80) : [];
    const matchedProjects = new Set(projects.map(project => project.id));
    const otherMatches = taskMatches.filter(task => !matchedProjects.has(task.projectId) || q);
    const globalStats = Store.globalProgress();
    return '<section class="library-hero"><div class="library-hero-copy"><p class="eyebrow"><span class="dot"></span> Curriculum library</p><h1>Ten complete Laravel applications.<br><em>One deliberate path through each.</em></h1><p>Every project is an independent product with its own repository, MySQL database, authentication, authorization, domain modules, advanced engineering, tests, security review, deployment runbook and release gate.</p><div class="heading-actions"><button class="btn btn-outline" data-action="export-curriculum">' + icon('file-earmark-arrow-down') + ' Export all 10 plans</button><a class="btn btn-accent" href="' + UI.roadmapUrl(Store.get().activeProjectId) + '">' + icon('map') + ' Active roadmap</a></div></div><div class="library-hero-stats"><div><strong>10</strong><span>independent apps</span></div><div><strong>100</strong><span>domain modules</span></div><div><strong>' + globalStats.total.toLocaleString('en-US') + '</strong><span>micro-steps</span></div><div><strong>100</strong><span>advanced features</span></div><div><strong>1,740</strong><span>code references</span></div><div><strong>' + globalStats.completed + '</strong><span>steps completed</span></div></div></section>' +
      '<form class="filter-bar" method="get" action="projects.html" role="search"><div class="filter-search">' + icon('search') + '<label class="visually-hidden" for="q">Search projects and tasks</label><input id="q" name="q" type="search" value="' + esc(q) + '" placeholder="Search project, module, or task title…"></div><select name="status" class="form-select" aria-label="Filter by project status"><option value="all">All statuses</option>' + [['not_started', 'Not started'], ['in_progress', 'In progress'], ['blocked', 'Blocked'], ['completed', 'Completed']].map(([value, label]) => '<option value="' + value + '"' + (status === value ? ' selected' : '') + '>' + label + '</option>').join('') + '</select><select name="category" class="form-select" aria-label="Filter by category"><option value="all">All categories</option>' + categories.map(item => '<option value="' + esc(item) + '"' + (category === item ? ' selected' : '') + '>' + esc(item) + '</option>').join('') + '</select><select name="sort" class="form-select" aria-label="Sort projects"><option value="number"' + (sort === 'number' ? ' selected' : '') + '>Project number</option><option value="progress"' + (sort === 'progress' ? ' selected' : '') + '>Progress</option><option value="name"' + (sort === 'name' ? ' selected' : '') + '>Name</option></select><button class="btn btn-outline" type="submit">Apply</button>' + (q || status !== 'all' || category !== 'all' ? '<a class="btn btn-quiet" href="projects.html">Clear</a>' : '') + '</form>' +
      '<div class="results-meta"><span>' + projects.length + ' project' + (projects.length === 1 ? '' : 's') + '</span>' + (q ? '<span>' + taskMatches.length + ' matching micro-steps' + (taskMatches.length === 80 ? ' (showing first 80)' : '') + '</span>' : '') + '</div>' +
      (projects.length ? '<div class="project-grid">' + projects.map(project => {
        const p = Store.progress(project.id);
        return '<article class="project-card"><div class="project-card-top"><span class="project-number">' + String(project.number).padStart(2, '0') + '</span><span class="project-category">' + esc(project.category) + '</span>' + UI.projectStatusBadge(project.id) + '</div><h3><a href="' + UI.projectUrl(project.id) + '">' + esc(project.title) + '</a></h3><p>' + esc(project.tagline) + '</p><div class="project-tags"><span>' + icon('diagram-3') + ' ' + project.modules.length + ' modules</span><span>' + icon('list-check') + ' ' + p.total + ' steps</span><span>' + icon('speedometer2') + ' ' + esc(project.difficulty) + '</span></div><div class="project-progress"><div><span>Progress</span><strong>' + p.percent + '%</strong></div>' + UI.progressBar(p.percent, project.title + ' progress') + '<small>' + p.completed + ' of ' + p.total + ' mandatory steps</small></div><div class="project-card-actions"><a class="btn btn-outline btn-sm" href="' + UI.projectUrl(project.id) + '">Details</a><a class="btn btn-quiet btn-sm" href="' + UI.roadmapUrl(project.id) + '">Roadmap ' + icon('arrow-right') + '</a></div></article>';
      }).join('') + '</div>' : UI.emptyState('No projects match those filters', 'Clear the search or choose a different status and category.', '<a class="btn btn-outline" href="projects.html">Clear filters</a>')) +
      (q ? '<section class="panel task-matches"><div class="panel-head"><div><h2>Matching micro-steps</h2><p>' + taskMatches.length + ' tasks across the curriculum match “' + esc(q) + '”.</p></div></div>' + (otherMatches.length ? '<div class="task-match-list">' + otherMatches.slice(0, 80).map(task => { const status = Store.statusOf(task.id); return '<a class="task-match" href="' + UI.taskUrl(task.id) + '"><span class="task-match-project">' + esc(UI.projectLabel(task.projectId)) + '</span><div><strong>' + esc(task.title) + '</strong><small>' + esc(task.module) + ' · Phase ' + task.phase + ' · ' + esc(UI.effortLabel(task.effort)) + '</small></div>' + UI.statusBadge(status) + '</a>'; }).join('') + '</div>' : '<div class="empty-inline">' + icon('search') + '<span>No micro-step titles match this search.</span></div>') + '</section>' : '');
  }

  function moduleRows(project) {
    const curriculum = LM.curricula[project.id];
    return curriculum.coverage.map((row, index) => {
      const module = row.module;
      const tasks = curriculum.tasks.filter(task => task.moduleId === module.id);
      const done = tasks.filter(task => Store.statusOf(task.id) === 'completed').length;
      const percent = tasks.length ? Math.round(done / tasks.length * 100) : 0;
      return '<tr><td><div class="module-cell"><span class="module-number">' + String(index + 1).padStart(2, '0') + '</span><div><strong>' + esc(module.name) + '</strong><small>' + esc(module.entity) + ' · <code>' + esc(module.table) + '</code></small></div></div></td><td><div class="coverage-tasks"><a href="' + UI.taskUrl(row.requirements) + '">Requirements</a><a href="' + UI.taskUrl(row.schema) + '">Migration</a><a href="' + UI.taskUrl(row.model) + '">Model</a><a href="' + UI.taskUrl(row.routes) + '">Routes</a><a href="' + UI.taskUrl(row.controller) + '">Controller</a><a href="' + UI.taskUrl(row.service) + '">Service</a><a href="' + UI.taskUrl(row.authorization) + '">Authorization</a><a href="' + UI.taskUrl(row.views) + '">Views</a><a href="' + UI.taskUrl(row.validationTests) + '">Validation tests</a><a href="' + UI.taskUrl(row.authorizationTests) + '">IDOR tests</a><a href="' + UI.taskUrl(row.security) + '">Security</a></div></td><td>' + module.routes.length + ' routes<br><code class="small-code">' + esc(module.permissions.split(',')[0].trim()) + '</code></td><td><div class="table-progress">' + UI.progressBar(percent, module.name + ' progress') + '<small>' + done + '/' + tasks.length + '</small></div></td><td><a class="text-link" href="' + UI.roadmapUrl(project.id, 'module=' + encodeURIComponent(module.id)) + '">' + tasks.length + ' steps ' + icon('arrow-right') + '</a></td></tr>';
    }).join('');
  }

  function readiness(projectId) {
    const curriculum = LM.curricula[projectId];
    const meta = Store.get().projects[projectId];
    const group = tasks => {
      const total = tasks.length;
      const done = tasks.filter(task => Store.statusOf(task.id) === 'completed').length;
      return { total, done, percent: total ? Math.round(done / total * 100) : 0 };
    };
    const functional = group(curriculum.tasks.filter(task => task.phase === 6));
    const testing = group(curriculum.tasks.filter(task => task.phase === 8));
    const security = group(curriculum.tasks.filter(task => task.phase === 5 || /security/i.test(task.key) || /security/i.test(task.title)));
    const documentation = group(curriculum.tasks.filter(task => task.phase === 10));
    const deployment = group(curriculum.tasks.filter(task => task.phase === 9));
    const git = meta.repoUrl ? (meta.gitCheckpoints.length ? 100 : 55) : 0;
    return [
      { key: 'functional', label: 'Functional implementation', percent: functional.percent, detail: functional.done + '/' + functional.total + ' module and advanced tasks', state: functional.percent === 100 ? 'Recorded complete' : 'In progress' },
      { key: 'testing', label: 'Testing', percent: testing.percent, detail: testing.done + '/' + testing.total + ' QA tasks', state: testing.percent === 100 ? 'Evidence recorded' : 'Pending verification' },
      { key: 'security', label: 'Security', percent: security.percent, detail: security.done + '/' + security.total + ' authorization and security tasks', state: security.percent === 100 ? 'Review recorded' : 'Review incomplete' },
      { key: 'documentation', label: 'Documentation', percent: documentation.percent, detail: documentation.done + '/' + documentation.total + ' release/documentation tasks', state: documentation.percent === 100 ? 'Release docs recorded' : 'Not finished' },
      { key: 'github', label: 'GitHub release state', percent: git, detail: meta.repoUrl ? (meta.gitCheckpoints.length + ' checkpoint(s) recorded · ' + meta.lastPushStatus) : 'Repository URL not recorded', state: meta.repoUrl ? 'Manual record' : 'Not recorded' },
      { key: 'deployment', label: 'Deployment readiness', percent: deployment.percent, detail: deployment.done + '/' + deployment.total + ' production tasks · ' + meta.deploymentStatus.replace(/_/g, ' '), state: meta.deploymentStatus === 'not_deployed' ? 'Not deployed' : meta.deploymentStatus.replace(/_/g, ' ') }
    ];
  }
  function advancedRows(project) {
    const tasks = LM.curricula[project.id].tasks.filter(task => task.moduleId === 'advanced');
    return '<div class="advanced-grid">' + tasks.map(task => {
      const status = Store.statusOf(task.id);
      return '<a class="advanced-card ' + (status === 'completed' ? 'advanced-done' : '') + '" href="' + UI.taskUrl(task.id) + '"><div class="advanced-card-top"><span class="advanced-mark">' + icon(status === 'completed' ? 'check2-circle' : 'shield-check') + '</span>' + UI.statusBadge(status) + '</div><strong>' + esc(task.title) + '</strong><p>' + esc(task.objective) + '</p><span class="advanced-link">Open task ' + icon('arrow-right') + '</span></a>';
    }).join('') + '</div>';
  }

  function completionGate(project) {
    const gate = Store.projectGate(project.id);
    const meta = Store.get().projects[project.id];
    return '<section class="panel" id="completion"><div class="panel-head"><div><h2>Project completion gate</h2><p>A project is complete only when every mandatory task and release record is verified. A percentage alone does not certify production readiness.</p></div>' + (gate.complete ? '<span class="badge-soft badge-green">' + icon('patch-check') + ' Complete</span>' : '<span class="badge-soft badge-amber">' + icon('hourglass-split') + ' Open</span>') + '</div>' +
      '<ul class="gate-list">' + gate.checklist.map(item => '<li class="' + (item.ok ? 'gate-ok' : 'gate-missing') + '">' + icon(item.ok ? 'check2-circle' : 'circle') + '<div><strong>' + esc(item.label) + '</strong><small>' + esc(item.detail) + '</small></div></li>').join('') + '</ul>' +
      '<div class="gate-actions">' + (gate.complete ? '<button class="btn btn-outline" data-action="reopen-project" data-project="' + project.id + '">' + icon('arrow-counterclockwise') + ' Reopen for improvements</button><a class="btn btn-accent" href="#final-report">View final report</a>' : '<button class="btn btn-accent" data-action="complete-project" data-project="' + project.id + '"' + (gate.allComplete && gate.repo && gate.evidence && gate.finalReport && gate.gitCheckpoint ? '' : ' disabled') + '>' + icon('patch-check') + ' Mark project complete</button><span class="gate-hint">' + (gate.allComplete ? 'Finish the project record fields below to unlock completion.' : 'Complete every mandatory task first. You can pause and resume at any time.') + '</span>') + '</div>' +
      '<form class="project-meta-form" data-project-meta-form data-project="' + project.id + '"><h3>Repository and release record</h3><p>These values are entered manually. The tracker cannot inspect Git, run tests or verify a deployment.</p><div class="form-grid"><label class="field"><span>GitHub repository URL</span><input type="url" name="repoUrl" value="' + esc(meta.repoUrl) + '" placeholder="https://github.com/you/repository"></label><label class="field"><span>Working branch</span><input type="text" name="branch" value="' + esc(meta.branch) + '" placeholder="main"></label><label class="field"><span>Last documented commit</span><input type="text" name="lastCommit" value="' + esc(meta.lastCommit) + '" placeholder="Commit hash"></label><label class="field"><span>Last push status</span><select name="lastPushStatus">' + ['Not pushed', 'Pushed', 'Push failed', 'Unknown'].map(value => '<option value="' + value + '"' + (meta.lastPushStatus === value ? ' selected' : '') + '>' + value + '</option>').join('') + '</select></label><label class="field"><span>Deployment status</span><select name="deploymentStatus">' + [['not_deployed', 'Not deployed'], ['staging', 'Staging'], ['production', 'Production'], ['deployment_failed', 'Deployment failed']].map(([value, label]) => '<option value="' + value + '"' + (meta.deploymentStatus === value ? ' selected' : '') + '>' + label + '</option>').join('') + '</select></label><label class="field"><span>Deployment URL (optional)</span><input type="url" name="deploymentUrl" value="' + esc(meta.deploymentUrl) + '" placeholder="https://"></label><label class="field field-wide"><span>Test execution evidence</span><textarea name="testEvidence" rows="3" minlength="20" placeholder="Command, date, environment and actual result. Do not claim tests you did not run.">' + esc(meta.testEvidence) + '</textarea></label><label class="field field-wide"><span>Final project report</span><textarea name="finalReport" rows="4" minlength="20" placeholder="Implemented modules, verification result, known limitations, deployment truth and future work.">' + esc(meta.finalReport) + '</textarea></label></div><div class="form-actions"><button class="btn btn-outline" type="submit">' + icon('save') + ' Save project record</button></div></form>' +
      '<div class="git-history"><h3>Recorded Git checkpoints</h3>' + (meta.gitCheckpoints.length ? '<ul class="checkpoint-list">' + meta.gitCheckpoints.map(item => '<li><span class="commit-dot">' + icon('git') + '</span><div><strong><code>' + esc(item.hash) + '</code> ' + esc(item.message) + '</strong><small>' + esc(item.branch) + ' · ' + esc(UI.formatDate(item.at)) + ' · ' + (item.pushed ? 'Pushed (self-reported)' : 'Not pushed') + (item.taskId && LM.taskIndex[item.taskId] ? ' · <a href="' + UI.taskUrl(item.taskId) + '">Task</a>' : '') + '</small></div></li>').join('') + '</ul>' : '<div class="empty-inline">' + icon('git') + '<span>No checkpoints recorded. Record one from each task’s Git checkpoint section.</span></div>') + '</div></section>';
  }

  function finalReport(project) {
    const meta = Store.get().projects[project.id];
    if (!meta.completedAt) return '';
    const p = Store.progress(project.id);
    const nextProject = LM.projects.find(item => item.number === project.number + 1);
    return '<section class="panel final-report" id="final-report"><div class="panel-head"><div><p class="eyebrow">Final report</p><h2>' + esc(project.title) + '</h2><p>Completed ' + esc(UI.formatDate(meta.completedAt)) + ' · ' + p.completed + ' mandatory micro-steps</p></div><span class="badge-soft badge-green">' + icon('patch-check') + ' Learner approved</span></div><div class="report-grid"><div><h3>Implemented modules</h3><ul>' + project.modules.map(module => '<li>' + esc(module.name) + '</li>').join('') + '</ul></div><div><h3>Recorded evidence</h3><p><strong>Repository:</strong> ' + (meta.repoUrl ? '<a href="' + esc(meta.repoUrl) + '" target="_blank" rel="noopener">' + esc(meta.repoUrl) + '</a>' : 'Not recorded') + '</p><p><strong>Deployment:</strong> ' + esc(meta.deploymentStatus.replace(/_/g, ' ')) + (meta.deploymentUrl ? ' · <a href="' + esc(meta.deploymentUrl) + '" target="_blank" rel="noopener">Open</a>' : '') + '</p><p><strong>Tests:</strong> ' + esc(meta.testEvidence) + '</p><p><strong>Skills practised:</strong> Laravel 12 architecture, authorization, validation, testing, Git, deployment planning and this project’s domain design.</p></div></div><div class="report-summary"><h3>Final project report</h3><p>' + esc(meta.finalReport) + '</p><h3>Remaining optional enhancements</h3><ul>' + project.future.map(item => '<li>' + esc(item) + '</li>').join('') + '</ul><h3>Next recommendation</h3><p>' + (nextProject ? 'Continue to <a href="' + UI.projectUrl(nextProject.id) + '">Project ' + String(nextProject.number).padStart(2, '0') + ' — ' + esc(nextProject.title) + '</a>. Each project remains independent; no shared database or codebase is assumed.' : 'You have completed the final project in this ten-project sequence. Revisit any completed project for enhancements without erasing its original completion history.') + '</p></div></section>';
  }

  function renderProject(query) {
    const projectId = query.project || Store.get().activeProjectId;
    const project = LM.projects.find(item => item.id === projectId);
    if (!project) { UI.renderErrorPage('Project not found', 'Choose one of the ten projects in the library.'); return; }
    const p = Store.progress(project.id);
    const meta = Store.get().projects[project.id];
    const gates = Store.projectGate(project.id);
    Store.focus(project.id);
    const next = Store.recommendation(project.id);
    document.title = project.title + ' · Laravel Mastery';
    const curriculum = LM.curricula[project.id];
    const phaseData = Store.phaseProgress(project.id);
    const projectIcons = ['building','bag-heart','layers','mortarboard','people','kanban','calendar2-check','headset','file-earmark-check','share'];
    const projectIcon = projectIcons[project.number - 1];
    return '<section class="project-hero project-hero-' + project.number + '"><div class="project-hero-main"><a class="back-link back-link-light" href="projects.html">' + icon('arrow-left') + ' All projects</a><div class="project-hero-badge"><span class="ph-icon">' + icon(projectIcon) + '</span><span>PROJECT ' + String(project.number).padStart(2, '0') + '</span><span class="ph-cat">' + esc(project.category) + '</span></div><h1>' + esc(project.title) + '</h1><p>' + esc(project.tagline) + '</p><div class="meta-line meta-line-light"><span>' + icon('speedometer2') + ' ' + esc(project.difficulty) + '</span><span>' + icon('clock') + ' ' + esc(project.effort) + '</span><span>' + icon('list-check') + ' ' + p.total + ' mandatory steps</span><span>' + icon('diagram-3') + ' ' + project.modules.length + ' modules</span><span>' + icon('shield-check') + ' 10 advanced tasks</span></div></div><div class="project-hero-side"><div class="ph-progress"><div class="ph-ring" style="--percent:' + p.percent + '"><span>' + p.percent + '%</span></div><div><span>Project completion</span><strong>' + p.completed + ' of ' + p.total + '</strong><small>' + p.blocked + ' blocked · ' + p.notStarted + ' not started</small></div></div><div class="ph-actions"><a class="btn btn-hero" href="' + UI.roadmapUrl(project.id) + '">' + icon('map') + ' Open roadmap</a>' + (meta.repoUrl ? '<a class="btn btn-ghost-hero" href="' + esc(meta.repoUrl) + '" target="_blank" rel="noopener">' + icon('github') + ' Repository</a>' : '<a class="btn btn-ghost-hero" href="#completion">' + icon('github') + ' Record repository</a>') + '</div></div></section>' +
      '<div class="project-summary-grid"><article class="panel summary-main"><div class="summary-progress"><div><p class="eyebrow">Completion</p><strong>' + p.percent + '%</strong><span>' + p.completed + ' of ' + p.total + ' mandatory micro-steps</span></div><div class="ring" style="--percent:' + p.percent + '"><span>' + p.percent + '%</span></div></div>' + UI.progressBar(p.percent, project.title + ' completion') + '<div class="summary-chips"><span>' + p.blocked + ' blocked</span><span>' + p.inProgress + ' in progress</span><span>' + p.notStarted + ' not started</span></div><div class="panel-actions">' + (next ? '<a class="btn btn-accent btn-sm" href="' + UI.taskUrl(next.id) + '">' + icon('arrow-right') + ' ' + (p.completed ? 'Continue' : 'Start') + ' with ' + esc(next.title.slice(0, 48)) + (next.title.length > 48 ? '…' : '') + '</a>' : '<a class="btn btn-outline btn-sm" href="#completion">Review completion gate</a>') + '<a class="btn btn-outline btn-sm" href="' + UI.roadmapUrl(project.id, 'status=blocked') + '">Blockers</a></div></article>' +
      '<article class="panel summary-side"><h3>Project gate</h3><div class="gate-summary">' + gates.checklist.map(item => '<div class="' + (item.ok ? 'ok' : 'missing') + '">' + icon(item.ok ? 'check2-circle' : 'circle') + '<span>' + esc(item.label) + '</span></div>').join('') + '</div><a class="text-link" href="#completion">Open completion records ' + icon('arrow-right') + '</a></article></div>' +
      '<section class="panel readiness-panel"><div class="panel-head"><div><h2>Readiness signals</h2><p>Each signal is computed from completed mandatory tasks and your recorded project metadata. They are not independent audits.</p></div></div><div class="readiness-grid">' + readiness(project.id).map(signal => '<div class="readiness-card readiness-' + signal.key + '"><div class="readiness-top"><span>' + esc(signal.label) + '</span><strong>' + signal.percent + '%</strong></div>' + UI.progressBar(signal.percent, signal.label + ' readiness') + '<p>' + esc(signal.state) + ' · ' + esc(signal.detail) + '</p></div>').join('') + '</div></section>' +
      '<nav class="tab-nav" aria-label="Project sections"><a href="#overview">Overview</a><a href="#architecture">Architecture</a><a href="#modules">Modules & coverage</a><a href="#advanced">Advanced features</a><a href="#requirements">Requirements</a><a href="#completion">Completion & Git</a>' + (meta.completedAt ? '<a href="#final-report">Final report</a>' : '') + '</nav>' +
      '<div class="project-detail-grid"><div class="project-detail-main">' +
      '<section class="panel" id="overview"><div class="panel-head"><h2>Product overview</h2><span class="badge-soft">' + esc(project.category) + '</span></div><h3>Purpose</h3><p>' + esc(project.purpose) + '</p><h3>Target users</h3><div class="tag-list">' + project.users.map(user => '<span>' + esc(user) + '</span>').join('') + '</div><h3>Scope exclusions</h3><ul class="reason-list">' + project.excluded.map(item => '<li><strong>' + esc(item.item) + '</strong><span>' + esc(item.reason) + '</span></li>').join('') + '</ul><h3>Future enhancements</h3><ul>' + project.future.map(item => '<li>' + esc(item) + '</li>').join('') + '</ul></div>' +
      '<section class="panel" id="architecture"><div class="panel-head"><h2>Architecture & ownership</h2></div><p>' + esc(project.architecture) + '</p><div class="callout">' + icon('diagram-3') + '<div><strong>Entity model</strong><p>' + esc(project.entityNote) + '</p></div></div>' +
      '<h3>Traceable module contracts</h3><p>Every module specification below maps to its own requirements, schema, routes, policy, views, tests and security review tasks. Open a contract to see the tables, ownership fields, permissions and endpoints you will implement.</p><div class="contract-list">' + project.modules.map((module, index) => '<details class="contract"><summary><span class="contract-index">' + String(index + 1).padStart(2, '0') + '</span><span class="contract-title"><strong>' + esc(module.name) + '</strong><small><code>' + esc(module.table) + '</code> · ' + module.routes.length + ' routes · ' + esc(module.permissions) + '</small></span>' + icon('chevron-down') + '</summary><div class="contract-body"><div class="contract-cols"><div><h4>Model & schema</h4><p><strong>' + esc(module.entity) + '</strong> · <code>app/Models/' + esc(module.entity) + '.php</code></p><ul class="schema-list">' + module.columns.map(column => '<li><code>' + esc(column) + '</code></li>').join('') + '</ul></div><div><h4>Relationships</h4><ul class="relation-list">' + module.relations.map(relation => '<li>' + esc(relation.replace(/:/g, ' → ')) + '</li>').join('') + '</ul><h4>Permissions</h4><p class="permission-line">' + module.permissions.split(',').map(permission => '<code>' + esc(permission.trim()) + '</code>').join(' ') + '</p><h4>Tests to write</h4><ul class="relation-list">' + module.tests.map(test => '<li>' + esc(test) + '</li>').join('') + '</ul></div></div><h4>Route map</h4><div class="table-responsive"><table class="data-table route-table"><thead><tr><th>Method</th><th>URI</th><th>Name</th><th>Controller</th><th>Middleware</th><th>Request</th></tr></thead><tbody>' + module.routes.map(route => { const parts = route.split('|').map(part => part.trim()); const methodUri = parts[0].split(/\s+/); return '<tr><td><span class="method-badge method-' + methodUri[0].toLowerCase() + '">' + esc(methodUri[0]) + '</span></td><td><code>' + esc(methodUri.slice(1).join(' ')) + '</code></td><td>' + esc(parts[1] || '') + '</td><td>' + esc(parts[2] || '') + '</td><td>web</td><td>' + esc(/Request/.test(parts[2] || '') ? '' : 'Form Request') + '</td></tr>'; }).join('') + '</tbody></table></div><div class="callout warn contract-security">' + icon('shield-check') + '<div><strong>Security requirement</strong><p>' + esc(module.security) + '</p></div></div><a class="btn btn-outline btn-sm" href="' + UI.roadmapUrl(project.id, 'module=' + encodeURIComponent(module.id)) + '">Open ' + '20' + ' module steps ' + icon('arrow-right') + '</a></div></details>').join('') + '</div><h3>Testing strategy</h3><p>' + esc(project.testing) + '</p>' + UI.codeBlock("Organizations / Tenants / Workspaces\n   └── owned records (enforced server-side)\n          ├── module policies\n          ├── actions and transactions\n          └── feature + authorization tests", 'Ownership boundary') + '</section>' +
      '<section class="panel" id="modules"><div class="panel-head"><div><h2>Modules and coverage matrix</h2><p>Implementation work is traceable to requirements, schema, routes, authorization, tests and security reviews.</p></div><span class="badge-soft">' + project.modules.length + ' modules</span></div><div class="table-responsive"><table class="data-table coverage-table"><thead><tr><th>Module</th><th>Task traceability</th><th>Contracts</th><th>Progress</th><th></th></tr></thead><tbody>' + moduleRows(project) + '</tbody></table></div></section>' +
      '<section class="panel" id="advanced"><div class="panel-head"><div><h2>Project-specific advanced features</h2><p>These cross-cutting requirements protect the hardest workflow, authorization, money and integration boundaries. Each is mandatory and independently verified.</p></div><span class="badge-soft">' + LM.curricula[project.id].tasks.filter(task => task.moduleId === 'advanced').length + ' tasks</span></div>' + advancedRows(project) + '</section>' +
      '<section class="panel" id="requirements"><div class="panel-head"><h2>Requirements & acceptance baseline</h2></div><h3>Functional requirements</h3><ol class="requirements-list">' + project.modules.map(module => '<li><strong>' + esc(module.name) + ':</strong> ' + esc(module.purpose) + ' <span class="req-routes">' + module.routes.length + ' routes · ' + esc(module.permissions) + '</span></li>').join('') + '</ol><h3>Non-functional baseline</h3><ul class="check-list"><li>Server-side authorization for every owned record and route.</li><li>Integer minor units for money; UTC storage with intentional display timezone.</li><li>Paginated lists, bounded search and indexes for measured query patterns.</li><li>Private storage for documents and attachments; escaped output.</li><li>Testing evidence recorded manually; no test is marked passed automatically.</li><li>Backup, restore, queue, scheduler and rollback rehearsed before production claims.</li></ul><h3>Completion requirements</h3><ul>' + project.completion.map(item => '<li>' + esc(item) + '</li>').join('') + '</ul>' + (project.codeNote ? '<div class="callout warn">' + icon('info-circle') + '<div><strong>Integration boundary</strong><p>' + esc(project.codeNote) + '</p></div></div>' : '') + '</section>' +
      completionGate(project) + finalReport(project) +
      '</div><aside class="project-detail-side"><section class="panel"><h3>Phase progress</h3><div class="phase-progress-list">' + phaseData.map(item => '<a href="' + UI.roadmapUrl(project.id, 'phase=' + item.phase.id) + '"><div><span>' + item.phase.id + '. ' + esc(item.phase.name) + '</span><strong>' + item.completed + '/' + item.total + '</strong></div>' + UI.progressBar(item.total ? Math.round(item.completed / item.total * 100) : 0, item.phase.name + ' progress') + '</a>').join('') + '</div></section><section class="panel"><h3>Project facts</h3><div class="stat-rows"><div><span>Curriculum tasks</span><strong>' + p.total + '</strong></div><div><span>Estimated effort</span><strong>' + esc(project.effort) + '</strong></div><div><span>Testing</span><strong>PHPUnit</strong></div><div><span>Stack</span><strong>Laravel 12 · MySQL · Blade</strong></div><div><span>Started</span><strong>' + (meta.startedAt ? esc(UI.formatDay(meta.startedAt)) : 'Not started') + '</strong></div><div><span>Deployment</span><strong>' + esc(meta.deploymentStatus.replace(/_/g, ' ')) + '</strong></div></div></section><section class="panel"><h3>Warnings</h3><p class="small-copy">Progress is local to this browser. A checked task is a learner assertion with acceptance confirmation—not an independent code or GitHub verification.</p><a class="btn btn-outline btn-sm w-100" href="settings.html">' + icon('download') + ' Export progress</a></section></aside></div>';
  }

  function matchesTask(task, q) { return !q || (task.title + ' ' + task.objective + ' ' + task.module + ' ' + task.action).toLowerCase().includes(q); }
  function taskRow(task) {
    const status = Store.statusOf(task.id);
    const dep = Store.dependenciesComplete(task.id);
    const blocked = status === 'blocked';
    return '<div class="task-row' + (status === 'completed' ? ' is-complete' : '') + '" data-task-id="' + task.id + '"><button type="button" class="task-check ' + status + '" data-action="' + (status === 'completed' ? 'incomplete-task' : 'complete-task') + '" data-task="' + task.id + '" aria-label="' + (status === 'completed' ? 'Mark incomplete: ' : 'Complete task: ') + esc(task.title) + '" title="' + (status === 'completed' ? 'Completed — click to reopen with confirmation' : 'Open completion confirmation') + '">' + icon(status === 'completed' ? 'check2' : blocked ? 'pause-fill' : 'circle') + '</button><div class="task-row-body"><div class="task-row-title"><a href="' + UI.taskUrl(task.id) + '">' + esc(task.title) + '</a>' + (Store.isBookmarked(task.id) ? '<span class="bookmark-mark" title="Bookmarked">' + icon('bookmark-fill') + '</span>' : '') + '</div><small>' + esc(task.module) + ' · ' + icon('clock') + ' ' + esc(UI.effortLabel(task.effort)) + (blocked ? ' · <span class="text-danger">Blocked</span>' : !dep ? ' · <span class="text-muted">Prerequisites incomplete</span>' : '') + '</small></div><span class="task-row-id">' + esc(task.id) + '</span>' + UI.statusBadge(status) + '<a class="task-open" href="' + UI.taskUrl(task.id) + '" aria-label="Open task">' + icon('chevron-right') + '</a></div>';
  }

  function phaseBody(tasks, activeTask) {
    const groups = [];
    const map = new Map();
    tasks.forEach(task => {
      const groupKey = task.moduleId || ('foundation-' + task.phase);
      if (!map.has(groupKey)) {
        const group = { name: task.module, moduleId: groupKey, tasks: [] };
        map.set(groupKey, group);
        groups.push(group);
      }
      map.get(groupKey).tasks.push(task);
    });
    return groups.map(group => '<div class="module-group" data-module="' + group.moduleId + '"><div class="module-group-head"><span class="module-group-title">' + esc(group.name) + '</span><span class="module-group-count">' + group.tasks.length + ' visible step' + (group.tasks.length === 1 ? '' : 's') + '</span></div>' + group.tasks.map(task => {
      const status = Store.statusOf(task.id);
      const isOpenTask = activeTask && activeTask.id === task.id;
      return '<div class="task-row' + (status === 'completed' ? ' is-complete' : '') + (isOpenTask ? ' current-task' : '') + '"><button type="button" class="task-check ' + status + '" data-action="' + (status === 'completed' ? 'incomplete-task' : 'complete-task') + '" data-task="' + task.id + '" aria-label="' + (status === 'completed' ? 'Mark incomplete: ' : 'Complete task: ') + esc(task.title) + '" title="' + (status === 'completed' ? 'Completed — reopen with confirmation' : 'Complete after confirming acceptance') + '">' + icon(status === 'completed' ? 'check2' : status === 'blocked' ? 'pause-fill' : 'circle') + '</button><div class="task-row-body"><div class="task-row-title"><a href="' + UI.taskUrl(task.id) + '">' + esc(task.title) + '</a>' + (isOpenTask ? '<span class="current-mark">CURRENT</span>' : '') + (Store.isBookmarked(task.id) ? '<span class="bookmark-mark" title="Bookmarked">' + icon('bookmark-fill') + '</span>' : '') + '</div><small>' + esc(UI.effortLabel(task.effort)) + (status === 'blocked' ? ' · <span class="text-danger">Blocked</span>' : !Store.dependenciesComplete(task.id) ? ' · <span class="text-muted">Prerequisites incomplete</span>' : '') + '</small></div><span class="task-row-id">' + esc(task.id) + '</span>' + UI.statusBadge(status) + '<a class="task-open" href="' + UI.taskUrl(task.id) + '" aria-label="Open ' + esc(task.title) + '">' + icon('chevron-right') + '</a></div>';
    }).join('') + '</div>').join('');
  }

  function renderRoadmap(query) {
    const projectId = query.project || Store.get().activeProjectId;
    const project = LM.projects.find(item => item.id === projectId);
    if (!project) { UI.renderErrorPage('Project not found', 'Open one of the ten projects from the library.'); return; }
    const curriculum = LM.curricula[project.id];
    const phaseFilter = query.phase ? Number(query.phase) : 0;
    const statusFilter = query.status || 'all';
    const moduleFilter = query.module || 'all';
    const q = (query.q || '').toLowerCase().trim();
    const activeTask = Store.get().activeTaskId && LM.taskIndex[Store.get().activeTaskId] ? LM.taskIndex[Store.get().activeTaskId] : null;
    const activePhase = activeTask && activeTask.projectId === project.id ? activeTask.phase : 1;
    const phases = LM.phases.map(phase => {
      const tasks = curriculum.tasks.filter(task => {
        const status = Store.statusOf(task.id);
        if (phaseFilter && task.phase !== phaseFilter) return false;
        if (phase.id !== task.phase) return false;
        if (moduleFilter !== 'all' && task.moduleId !== moduleFilter) return false;
        if (statusFilter === 'actionable' && (status === 'completed' || status === 'blocked' || !Store.dependenciesComplete(task.id))) return false;
        if (statusFilter !== 'all' && statusFilter !== 'actionable' && status !== statusFilter) return false;
        return matchesTask(task, q);
      });
      const all = curriculum.tasks.filter(task => task.phase === phase.id);
      const done = all.filter(task => Store.statusOf(task.id) === 'completed').length;
      const blocked = all.filter(task => Store.statusOf(task.id) === 'blocked').length;
      return { phase, tasks, all, done, blocked };
    });
    const visible = phases.filter(item => item.all.length);
    const p = Store.progress(project.id);
    const modules = project.modules;
    document.title = project.title + ' roadmap · Laravel Mastery';
    return '<section class="page-heading roadmap-heading"><div><a class="back-link" href="' + UI.projectUrl(project.id) + '">' + icon('arrow-left') + ' Project overview</a><p class="eyebrow">' + String(project.number).padStart(2, '0') + ' · ' + esc(project.category) + '</p><h1>' + esc(project.title) + ' roadmap</h1><p>' + p.completed + ' of ' + p.total + ' mandatory micro-steps completed · ' + p.percent + '%</p></div><div class="heading-actions"><button class="btn btn-outline" data-action="export-progress">' + icon('download') + ' Backup</button><a class="btn btn-accent" href="' + (Store.continueTarget().task ? UI.taskUrl(Store.continueTarget().task.id) : UI.projectUrl(project.id) + '#completion') + '">' + icon('play-fill') + ' Continue</a></div></section>' +
      '<div class="roadmap-progress panel"><div class="roadmap-progress-top"><div><strong>' + p.percent + '% complete</strong><span>' + p.completed + ' verified steps · ' + p.blocked + ' blocked · ' + (p.total - p.completed) + ' remaining</span></div><div class="roadmap-project-picker"><label for="project-picker">Project</label><select id="project-picker" class="form-select form-select-sm" data-project-picker>' + LM.projects.map(item => '<option value="' + item.id + '"' + (item.id === project.id ? ' selected' : '') + '>P' + String(item.number).padStart(2, '0') + ' — ' + esc(item.title) + '</option>').join('') + '</select></div></div>' + UI.progressBar(p.percent, project.title + ' progress') + '<div class="phase-strip">' + Store.phaseProgress(project.id).map(item => '<a href="' + UI.roadmapUrl(project.id, 'phase=' + item.phase.id) + '" class="phase-chip' + (phaseFilter === item.phase.id ? ' active' : '') + '"><span>' + item.phase.id + '</span><div><strong>' + esc(item.phase.short) + '</strong><small>' + item.completed + '/' + item.total + '</small></div></a>').join('') + '</div></div>' +
      '<form class="filter-bar roadmap-filters" method="get" action="roadmap.html"><input type="hidden" name="project" value="' + project.id + '"><div class="filter-search">' + icon('search') + '<label class="visually-hidden" for="task-q">Search tasks</label><input id="task-q" name="q" type="search" value="' + esc(q) + '" placeholder="Search title, module or action…"></div><select name="phase" class="form-select" aria-label="Filter phase"><option value="">All phases</option>' + LM.phases.map(phase => '<option value="' + phase.id + '"' + (phaseFilter === phase.id ? ' selected' : '') + '>' + phase.id + '. ' + esc(phase.name) + '</option>').join('') + '</select><select name="module" class="form-select" aria-label="Filter module"><option value="all">All modules</option>' + modules.map(module => '<option value="' + module.id + '"' + (moduleFilter === module.id ? ' selected' : '') + '>' + esc(module.name) + '</option>').join('') + '</select><select name="status" class="form-select" aria-label="Filter status"><option value="all">All statuses</option><option value="actionable"' + (statusFilter === 'actionable' ? ' selected' : '') + '>Actionable now</option><option value="not_started"' + (statusFilter === 'not_started' ? ' selected' : '') + '>Not started</option><option value="in_progress"' + (statusFilter === 'in_progress' ? ' selected' : '') + '>In progress</option><option value="blocked"' + (statusFilter === 'blocked' ? ' selected' : '') + '>Blocked</option><option value="completed"' + (statusFilter === 'completed' ? ' selected' : '') + '>Completed</option></select><button class="btn btn-outline" type="submit">Filter</button><a class="btn btn-quiet" href="roadmap.html?project=' + project.id + '">Reset</a></form>' +
      '<div class="roadmap-meta"><span>' + visible.reduce((sum, item) => sum + item.tasks.length, 0) + ' matching tasks</span><span>All tasks are mandatory unless explicitly marked optional (none in this curriculum).</span></div>' +
      (visible.length ? visible.map(item => {
        const open = phaseFilter === item.phase.id || (!phaseFilter && activePhase === item.phase.id) || (q && item.tasks.length);
        return '<details class="phase-section" ' + (open ? 'open' : '') + ' id="phase-' + item.phase.id + '"><summary><span class="phase-index">Phase ' + item.phase.id + '</span><div><strong>' + esc(item.phase.name) + '</strong><small>' + item.done + '/' + item.all.length + ' completed' + (item.blocked ? ' · ' + item.blocked + ' blocked' : '') + '</small></div>' + UI.progressBar(item.all.length ? Math.round(item.done / item.all.length * 100) : 0, item.phase.name) + icon('chevron-down') + '</summary><div class="phase-body">' + phaseBody(item.tasks, activeTask) + '</div></details>';
      }).join('') : UI.emptyState('No matching tasks', 'Adjust the search or filters. Your saved progress has not changed.', '<a class="btn btn-outline" href="roadmap.html?project=' + project.id + '">Clear filters</a>'));
  }

  function acceptanceChecks(task) {
    return '<ol class="acceptance-list">' + task.acceptance.map((item, index) => '<li><label class="acceptance-row"><input type="checkbox" name="accept-' + index + '" data-acceptance value="' + index + '"><span>' + esc(item) + '</span></label></li>').join('') + '</ol>';
  }

  function renderTaskPage(query) {
    const taskId = query.task;
    const task = taskId ? LM.taskIndex[taskId] : null;
    if (!task) { UI.renderErrorPage('Task not found', 'The task ID is missing or does not belong to this curriculum. Open a roadmap to choose a real task.'); return; }
    const project = LM.projects.find(item => item.id === task.projectId);
    const status = Store.statusOf(task.id);
    const record = Store.recordFor(task.id) || {};
    const blocked = !!record.blockedReason;
    const deps = task.dependencies.map(id => LM.taskIndex[id]).filter(Boolean);
    const missingDeps = deps.filter(item => Store.statusOf(item.id) !== 'completed');
    const next = task.nextId ? LM.taskIndex[task.nextId] : null;
    const related = (task.related || []).map(id => LM.taskIndex[id]).filter(Boolean);
    const projectMeta = Store.get().projects[task.projectId];
    const phaseTasks = LM.curricula[task.projectId].tasks.filter(item => item.phase === task.phase);
    const doneInPhase = phaseTasks.filter(item => Store.statusOf(item.id) === 'completed').length;
    Store.focus(task.projectId, task.id);
    document.title = task.title + ' · ' + project.title;
    return '<div class="task-page"><section class="task-header">' +
      '<div class="phase-stepper" aria-label="Project phases">' + LM.phases.map(phase => {
        const phaseTasks = LM.curricula[task.projectId].tasks.filter(item => item.phase === phase.id);
        const phaseDone = phaseTasks.filter(item => Store.statusOf(item.id) === 'completed').length;
        const phaseState = phase.id === task.phase ? 'current' : phaseDone === phaseTasks.length ? 'done' : phaseDone ? 'partial' : '';
        return '<a class="stepper-item ' + phaseState + '" href="' + UI.roadmapUrl(task.projectId, 'phase=' + phase.id) + '" title="' + esc(phase.name) + '"><span>' + (phaseDone === phaseTasks.length ? icon('check2') : phase.id) + '</span><small>' + esc(phase.short) + '</small></a>';
      }).join('') + '</div>' +
      '<div class="task-breadcrumb"><a href="' + UI.projectUrl(project.id) + '">' + esc(project.title) + '</a>' + icon('chevron-right') + '<a href="' + UI.roadmapUrl(project.id, 'phase=' + task.phase) + '">Phase ' + task.phase + ': ' + esc(task.phaseName) + '</a>' + icon('chevron-right') + '<span>' + esc(task.module) + '</span></div>' +
      '<div class="task-title-row"><div><div class="task-badges">' + UI.statusBadge(status) + '<span class="badge-soft">' + esc(task.id) + '</span><span class="badge-soft">' + esc(UI.effortLabel(task.effort)) + '</span>' + (Store.isBookmarked(task.id) ? '<span class="badge-soft badge-amber">' + icon('bookmark-fill') + ' Bookmarked</span>' : '') + '</div><h1>' + esc(task.title) + '</h1><p>' + esc(task.objective) + '</p></div><div class="task-header-actions"><button class="btn btn-outline btn-sm" type="button" data-action="copy-task-markdown" data-task="' + task.id + '">' + icon('clipboard') + ' Copy Markdown</button><button class="btn btn-outline btn-sm" type="button" data-action="bookmark-task" data-task="' + task.id + '">' + icon(Store.isBookmarked(task.id) ? 'bookmark-fill' : 'bookmark') + ' ' + (Store.isBookmarked(task.id) ? 'Bookmarked' : 'Bookmark') + '</button><button class="btn btn-outline btn-sm" type="button" data-action="toggle-notes">' + icon('journal-text') + ' Personal notes</button></div></div>' +
      '<div class="task-context-bar"><div><span>Project</span><strong>' + String(project.number).padStart(2, '0') + ' · ' + esc(project.title) + '</strong></div><div><span>Phase</span><strong>' + task.phase + ' · ' + esc(task.phaseName) + '</strong></div><div><span>Module</span><strong>' + esc(task.module) + '</strong></div><div><span>Phase progress</span><strong>' + doneInPhase + '/' + phaseTasks.length + '</strong></div></div>' +
      '<div class="task-action-bar">' + (status === 'not_started' ? '<button class="btn btn-accent" data-action="start-task" data-task="' + task.id + '">' + icon('play-fill') + ' Start task</button>' : '') + (status !== 'completed' ? '<button class="btn ' + (status === 'not_started' ? 'btn-outline' : 'btn-accent') + '" data-action="complete-task" data-task="' + task.id + '">' + icon('check2-circle') + ' Mark complete</button>' : '<button class="btn btn-outline" data-action="incomplete-task" data-task="' + task.id + '">' + icon('arrow-counterclockwise') + ' Mark incomplete</button>') + (blocked ? '<button class="btn btn-outline" data-action="unblock-task" data-task="' + task.id + '">' + icon('play-circle') + ' Unblock</button>' : '<button class="btn btn-quiet" data-action="block-task" data-task="' + task.id + '">' + icon('pause-circle') + ' Block task</button>') + '<a class="btn btn-quiet" href="#git-checkpoint">' + icon('git') + ' Git checkpoint</a></div>' +
      (missingDeps.length ? '<div class="dependency-warning">' + icon('signpost-2') + '<div><strong>Prerequisites incomplete</strong><p>Complete ' + missingDeps.map(item => '<a href="' + UI.taskUrl(item.id) + '">' + esc(item.title) + '</a>').join(', ') + ' before marking this task complete.</p></div></div>' : '') + (blocked ? '<div class="blocked-banner">' + icon('pause-octagon') + '<div><strong>Blocked</strong><p>' + esc(record.blockedReason) + '</p></div><button class="btn btn-outline btn-sm" data-action="unblock-task" data-task="' + task.id + '">Resolve blocker</button></div>' : '') + '</section>' +
      '<div class="task-layout"><div class="task-main">' +
      '<section class="panel task-section"><h2><span>1</span> Why this task matters</h2><p>' + esc(task.why) + '</p><div class="task-requirement"><strong>Expected result</strong><p>' + esc(task.expected) + '</p></div></section>' +
      '<section class="panel task-section"><h2><span>2</span> Exact action</h2><p>' + esc(task.action) + '</p><div class="file-callout"><span>Files / paths</span><code>' + esc(task.files) + '</code></div>' + UI.commandBlock(task.command) + '<h3>Where the code belongs</h3><p>' + esc(task.codeLocation || task.files) + '</p>' + (task.code ? UI.codeBlock(task.code, 'Reference implementation for this task') + '<h3>Important code sections</h3><p>' + esc(task.explanation) + '</p>' : '<div class="empty-inline">' + icon('file-earmark-text') + '<span>This task produces documentation, verification, a Git checkpoint or a manual operation rather than application code.</span></div>') + '</section>' +
      '<section class="panel task-section"><h2><span>3</span> Verification</h2><p>' + esc(task.verify) + '</p><div class="verify-grid"><div class="verify-card success"><strong>' + icon('check2-circle') + ' Positive cases</strong><p>' + esc(task.positive) + '</p></div><div class="verify-card danger"><strong>' + icon('x-octagon') + ' Negative / edge cases</strong><p>' + esc(task.negative) + '</p></div></div><h3>Common errors and fixes</h3><p>' + esc(task.errors) + '</p></section>' +
      '<section class="panel task-section"><h2><span>4</span> Acceptance criteria</h2><p>Check these against your actual implementation. Completion requires every item to be confirmed.</p>' + acceptanceChecks(task) + (record.completedAt ? '<div class="completion-record">' + icon('patch-check') + '<div><strong>Completed ' + esc(UI.formatDate(record.completedAt)) + '</strong><p>You confirmed all acceptance criteria. This record is your assertion; the tracker cannot inspect the codebase or GitHub.</p></div></div>' : '') + '</section>' +
      '<section class="panel task-section" id="git-checkpoint"><h2><span>5</span> Git checkpoint</h2><p>Review the diff, stage only reviewed files and create a real commit. The tracker records your manual evidence but cannot run Git or GitHub actions.</p>' + UI.codeBlock('git status --short\ngit diff --check\n# Stage reviewed files explicitly:\ngit add <file-1> <file-2>\ngit status --short\ngit commit -m "feat(' + task.projectId + '): ' + task.key + '"\n# Push only after verifying origin and branch:\ngit remote -v\ngit push -u origin HEAD', 'Checkpoint workflow') + '<div class="checkpoint-actions"><button class="btn btn-outline" data-action="record-git" data-task="' + task.id + '" data-project="' + task.projectId + '">' + icon('git') + ' Record checkpoint</button><a class="btn btn-quiet" href="' + UI.projectUrl(task.projectId) + '#completion">View project Git history</a></div></section>' +
      '<section class="panel task-section"><h2><span>6</span> Security review</h2><p>' + esc(task.security) + '</p><div class="callout">' + icon('shield-check') + '<div><strong>Verify, do not assume</strong><p>Add a negative test for unauthorized access, invalid input and duplicate actions where applicable. Record genuine evidence and keep the task incomplete if verification fails.</p></div></div></section>' +
      '<section class="panel task-section task-notes" id="task-notes"><h2><span>7</span> Personal notes</h2><p>Capture commands, observations, errors and decisions. Notes are stored only in this browser.</p><label class="visually-hidden" for="task-notes-input">Personal notes for this task</label><textarea id="task-notes-input" class="notes-area" rows="5" placeholder="What did you try? What failed? What should future you know?">' + esc(record.notes || '') + '</textarea><div class="form-actions"><button class="btn btn-outline" data-action="save-notes" data-task="' + task.id + '">' + icon('save') + ' Save notes</button><span class="small-copy" data-notes-status>No unsaved changes.</span></div></section>' +
      '<div class="task-nav"><a class="task-nav-prev" href="' + (task.previousId ? UI.taskUrl(task.previousId) : '#') + '" ' + (!task.previousId ? 'aria-disabled="true"' : '') + '>' + icon('arrow-left') + '<div><small>Previous task</small><strong>' + (task.previousId ? esc(LM.taskIndex[task.previousId].title) : 'Start of project') + '</strong></div></a><a class="task-nav-next" href="' + (next ? UI.taskUrl(next.id) : '#completion') + '"><div><small>Next task</small><strong>' + (next ? esc(next.title) : 'Project completion gate') + '</strong></div>' + icon('arrow-right') + '</a></div></div>' +
      '<aside class="task-side"><section class="panel"><h3>Task metadata</h3><dl class="meta-list"><div><dt>Task ID</dt><dd><code>' + esc(task.id) + '</code></dd></div><div><dt>Project</dt><dd>' + String(project.number).padStart(2, '0') + ' · ' + esc(project.title) + '</dd></div><div><dt>Phase</dt><dd>' + task.phase + ' · ' + esc(task.phaseName) + '</dd></div><div><dt>Module</dt><dd>' + esc(task.module) + '</dd></div><div><dt>Estimated effort</dt><dd>' + esc(UI.effortLabel(task.effort)) + '</dd></div><div><dt>Status</dt><dd>' + UI.statusLabel(status) + '</dd></div><div><dt>Required</dt><dd>Yes — counts toward progress</dd></div></dl></section>' +
      '<section class="panel module-contract"><h3>Module contract</h3><dl class="meta-list"><div><dt>Table</dt><dd><code>' + esc(task.coverage && task.coverage.table ? task.coverage.table : 'Multiple') + '</code></dd></div><div><dt>Entity</dt><dd>' + esc(task.coverage && task.coverage.entity ? task.coverage.entity : 'Cross-cutting') + '</dd></div><div><dt>Permissions</dt><dd><code>' + esc(task.coverage && task.coverage.permissions ? task.coverage.permissions : 'See policies') + '</code></dd></div><div><dt>Routes</dt><dd>' + (task.coverage && task.coverage.routes ? task.coverage.routes.length : 0) + ' documented</dd></div></dl>' + (task.coverage && task.coverage.routes && task.coverage.routes.length ? '<details class="contract mini"><summary>View route map ' + icon('chevron-down') + '</summary><ul class="route-mini-list">' + task.coverage.routes.map(route => '<li><code>' + esc(route) + '</code></li>').join('') + '</ul></details>' : '') + (task.coverage && task.coverage.tests && task.coverage.tests.length ? '<h4 class="side-subhead">Tests to write</h4><ul class="related-list">' + task.coverage.tests.map(test => '<li>' + esc(test) + '</li>').join('') + '</ul>' : '') + '<a class="text-link" style="margin-top:8px" href="' + UI.projectUrl(task.projectId) + '#architecture">Open full contracts ' + icon('arrow-right') + '</a></section>' +
      '<section class="panel"><h3>Prerequisites</h3>' + (deps.length ? '<ul class="dependency-list">' + deps.map(item => { const done = Store.statusOf(item.id) === 'completed'; return '<li><span class="dep-state ' + (done ? 'done' : 'pending') + '">' + icon(done ? 'check2' : 'circle') + '</span><div><a href="' + UI.taskUrl(item.id) + '">' + esc(item.title) + '</a><small>' + UI.statusLabel(Store.statusOf(item.id)) + '</small></div></li>'; }).join('') + '</ul>' : '<p class="small-copy">No prerequisite tasks. This is the first step of the project.</p>') + '</section>' +
      '<section class="panel"><h3>Unlocks</h3>' + (next ? '<a class="unlock-link" href="' + UI.taskUrl(next.id) + '">' + icon('arrow-right-circle') + '<div><strong>' + esc(next.title) + '</strong><small>Task ' + next.sequence + ' of ' + LM.curricula[next.projectId].tasks.length + '</small></div></a>' : '<p class="small-copy">This task leads to the project completion gate.</p>') + (related.length ? '<h4 class="side-subhead">Related tasks</h4><ul class="related-list">' + related.map(item => '<li><a href="' + UI.taskUrl(item.id) + '">' + esc(item.title) + '</a></li>').join('') + '</ul>' : '') + '</section>' +
      '<section class="panel side-help"><h3>Need to stop?</h3><p>Record a blocker or leave a note. Your position and completed tasks remain saved. Other projects stay available.</p><button class="btn btn-outline btn-sm w-100" data-action="block-task" data-task="' + task.id + '">' + icon('pause-circle') + ' Pause with blocker</button></section></aside></div></div>';
  }

  function renderProgress(query) {
    const global = Store.globalProgress();
    const state = Store.get();
    const recent = state.activity;
    const blocked = Object.entries(state.tasks).filter(([, record]) => record.blockedReason && !record.completedAt);
    const bookmarks = state.bookmarks.map(id => LM.taskIndex[id]).filter(Boolean);
    const phases = LM.projects.map(project => ({ project, phases: Store.phaseProgress(project.id) }));
    return '<section class="progress-hero"><div><p class="eyebrow"><span class="dot"></span> Progress and evidence</p><h1>Evidence over assumptions.</h1><p>Every percentage is calculated from completed mandatory tasks. Blockers are visible, optional ideas never lower completion, and the tracker never claims a test passed on your behalf.</p><div class="heading-actions"><button class="btn btn-outline" data-action="export-progress">' + icon('download') + ' Export backup</button><a class="btn btn-accent" href="' + (Store.continueTarget().task ? UI.taskUrl(Store.continueTarget().task.id) : 'index.html') + '">' + icon('play-fill') + ' Continue learning</a></div></div><div class="progress-hero-ring"><div class="ph-ring" style="--percent:' + global.percent + '"><span>' + global.percent + '%</span></div><div><span>Overall completion</span><strong>' + global.completed.toLocaleString('en-US') + ' of ' + global.total.toLocaleString('en-US') + '</strong><small>' + global.completedProjects + ' projects complete · ' + global.blocked + ' blocked</small></div></div></section>' +
      '<div class="metric-grid five"><article class="metric-card"><span class="metric-icon red">' + icon('pie-chart') + '</span><div><strong>' + global.percent + '%</strong><span>Overall completion</span></div></article><article class="metric-card"><span class="metric-icon blue">' + icon('list-check') + '</span><div><strong>' + global.completed + '<small>/' + global.total + '</small></strong><span>Micro-steps complete</span></div></article><article class="metric-card"><span class="metric-icon green">' + icon('folder2-open') + '</span><div><strong>' + global.completedProjects + '<small>/10</small></strong><span>Projects complete</span></div></article><article class="metric-card"><span class="metric-icon amber">' + icon('pause-circle') + '</span><div><strong>' + global.blocked + '</strong><span>Blocked tasks</span></div></article><article class="metric-card"><span class="metric-icon purple">' + icon('bookmark-star') + '</span><div><strong>' + bookmarks.length + '</strong><span>Bookmarked tasks</span></div></article></div>' +
      '<div class="progress-layout"><section class="panel"><div class="panel-head"><h2>Project completion</h2><span class="badge-soft">' + global.total + ' mandatory tasks</span></div><div class="project-progress-table">' + global.projects.map(item => { const gate = Store.projectGate(item.project.id); return '<div class="progress-project-row"><div class="ppr-title"><a href="' + UI.projectUrl(item.project.id) + '">' + String(item.project.number).padStart(2, '0') + ' · ' + esc(item.project.title) + '</a><div>' + UI.projectStatusBadge(item.project.id) + '<span class="small-copy">' + item.completed + '/' + item.total + (gate.complete ? ' · release complete' : gate.allComplete ? ' · ready for review' : '') + '</span></div></div>' + UI.progressBar(item.percent, item.project.title + ' progress') + '<div class="ppr-side"><strong>' + item.percent + '%</strong><span>' + item.blocked + ' blocked</span><a href="' + UI.roadmapUrl(item.project.id) + '">Roadmap ' + icon('arrow-right') + '</a></div></div>'; }).join('') + '</div></section>' +
      '<aside><section class="panel" id="blocked"><div class="panel-head"><h2>Blocked tasks</h2></div>' + (blocked.length ? '<ul class="blocked-list">' + blocked.map(([id, record]) => { const task = LM.taskIndex[id]; return '<li><div><a href="' + UI.taskUrl(id) + '">' + esc(task.title) + '</a><small>' + esc(task.projectId.toUpperCase()) + ' · ' + esc(task.module) + ' · ' + esc(UI.formatDate(record.blockedAt)) + '</small><p>' + esc(record.blockedReason) + '</p></div><button class="btn btn-outline btn-sm" data-action="unblock-task" data-task="' + id + '">Unblock</button></li>'; }).join('') + '</ul>' : '<div class="empty-inline">' + icon('check2-circle') + '<span>No blocked tasks.</span></div>') + '</section>' +
      '<section class="panel"><div class="panel-head"><h2>Bookmarks</h2></div>' + (bookmarks.length ? '<ul class="compact-task-list">' + bookmarks.map(task => '<li><span class="activity-icon">' + icon('bookmark') + '</span><div><a href="' + UI.taskUrl(task.id) + '">' + esc(task.title) + '</a><small>' + esc(UI.projectLabel(task.projectId)) + ' · ' + esc(task.module) + '</small></div></li>').join('') + '</ul>' : '<div class="empty-inline">' + icon('bookmark') + '<span>No bookmarks yet.</span></div>') + '</section></aside></div>' +
      '<section class="panel"><div class="panel-head"><h2>Phase-level progress</h2><p>Use this view to find the next incomplete phase rather than following an arbitrary task number.</p></div><div class="phase-matrix">' + phases.map(item => '<div class="phase-matrix-project"><h3><a href="' + UI.roadmapUrl(item.project.id) + '">' + String(item.project.number).padStart(2, '0') + ' · ' + esc(item.project.title) + '</a></h3><div class="phase-matrix-rows">' + item.phases.map(phase => '<div><span>' + phase.phase.id + '. ' + esc(phase.phase.short) + '</span>' + UI.progressBar(phase.total ? Math.round(phase.completed / phase.total * 100) : 0, phase.phase.name) + '<small>' + phase.completed + '/' + phase.total + '</small></div>').join('') + '</div></div>').join('') + '</div></section>' +
      '<section class="panel"><div class="panel-head"><h2>Activity history</h2><p>Timestamps are stored when you act. Reopening or unblocking does not erase prior events.</p></div>' + activityList(recent.slice(0, 100), 'No activity yet. Start a task or record a note.') + '</section>';
  }

  function renderSettings(query) {
    const state = Store.get();
    const snapshot = Store.snapshot();
    const global = Store.globalProgress();
    return '<section class="page-heading"><div><p class="eyebrow"><span class="dot"></span> Settings and data</p><h1>Protect your learning record</h1><p>There is no account and no backend for progress. Export JSON backups before clearing browser data or moving devices.</p></div><div class="heading-actions"><button class="btn btn-accent" data-action="export-progress">' + icon('download') + ' Export progress</button></div></section>' +
      (snapshot.blocked ? '<div class="start-banner danger">' + icon('exclamation-triangle') + '<div><strong>Storage protection is active</strong><p>' + esc(snapshot.readError || (snapshot.conflict ? 'Another browser tab changed the saved progress. Saving is paused so you do not overwrite it. Export any in-memory work, then reload the saved copy.' : 'The tracker cannot safely save to LocalStorage. Exporting is still available; do not reset until you have a backup.')) + '</p></div><button class="btn btn-outline btn-sm" data-action="recover-previous">Try previous copy</button></div>' : '') +
      '<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Storage status</h2><span class="' + (snapshot.blocked ? 'badge-soft badge-red' : 'badge-soft badge-green') + '">' + (snapshot.blocked ? 'Save paused' : 'Local saving active') + '</span></div><div class="stat-rows"><div><span>Storage key</span><strong><code>' + esc(Store.KEY) + '</code></strong></div><div><span>Schema version</span><strong>' + esc(Store.VERSION) + '</strong></div><div><span>Saved task records</span><strong>' + Object.keys(state.tasks).length + '</strong></div><div><span>Completed micro-steps</span><strong>' + global.completed + ' / ' + global.total + '</strong></div><div><span>Last saved</span><strong>' + esc(Store.lastSaved() ? UI.formatDate(Store.lastSaved()) : 'Not saved yet') + '</strong></div></div><div class="callout warn">' + icon('shield-lock') + '<div><strong>LocalStorage limits</strong><p>It is browser and device specific, can be cleared by the browser, is not encrypted and does not synchronize. Never store passwords, OAuth tokens, API secrets or real customer data in this tracker. Export a backup regularly.</p></div></div></section>' +
      '<section class="panel"><div class="panel-head"><h2>Import a backup</h2></div><p>Imports are validated against this curriculum before any existing progress is replaced. You will see a preview and choose merge or replace.</p><label class="field"><span>JSON backup file</span><input id="backup-file" type="file" accept="application/json,.json" data-import-input></label><div class="callout">' + icon('info-circle') + '<div><strong>Merge behavior</strong><p>Merge keeps your active project, unions completion records and notes, and prefers the latest completion timestamp. It never silently removes your current progress. Unknown task IDs are reported and skipped.</p></div></div><button class="btn btn-outline" data-action="recover-previous">' + icon('arrow-counterclockwise') + ' Recover previous local copy</button></section>' +
      '<section class="panel"><div class="panel-head"><h2>Learning preferences</h2></div><div class="preference-row"><div><strong>Theme</strong><p>Light or dark workspace. Progress is unaffected.</p></div><button class="btn btn-outline btn-sm" data-action="toggle-theme" aria-label="Toggle color theme"><i class="bi bi-' + (state.preferences.theme === 'dark' ? 'sun' : 'moon-stars') + '" aria-hidden="true"></i> <span data-theme-label>' + (state.preferences.theme === 'dark' ? 'Light theme' : 'Dark theme') + '</span></button></div><div class="preference-row"><div><strong>Curriculum scope</strong><p>3,330 micro-steps across ten independent Laravel 12 projects. All are mandatory.</p></div><span class="badge-soft">' + LM.projects.length + ' projects</span></div></section>' +
      '<section class="panel"><div class="panel-head"><h2>' + icon('journal-richtext') + ' Reference and deliverables</h2></div><p>Use the engineering handbook for setup, architecture, testing, security, Git recovery and deployment runbooks. Export project plans to work offline or share them with a reviewer.</p><div class="detail-actions"><a class="btn btn-outline" href="handbook.html">' + icon('journal-richtext') + ' Open handbook</a><button class="btn btn-outline" data-action="export-curriculum">' + icon('file-earmark-arrow-down') + ' Export all 10 project plans</button><a class="btn btn-outline" href="MANIFEST.md" target="_blank" rel="noopener">' + icon('clipboard-check') + ' Coverage manifest</a></div><div class="callout" style="margin-top:14px">' + icon('info-circle') + '<div><strong>Storage footprint estimate</strong><p>' + (JSON.stringify(Store.get()).length / 1024).toFixed(1) + ' KB of progress data is currently stored in this browser. Task curriculum data is separate and loaded from local assets.</p></div></div></section>' +
      '<section class="panel danger-zone"><div class="panel-head"><h2>Reset controls</h2></div><p>Resets require explicit confirmation. Export first; the previous local copy is best effort and cannot be guaranteed if storage is full or unavailable.</p><label class="field"><span>Reset a single project</span><select id="reset-project-select" class="form-select">' + LM.projects.map(project => '<option value="' + project.id + '">P' + String(project.number).padStart(2, '0') + ' — ' + esc(project.title) + '</option>').join('') + '</select></label><div class="danger-actions"><button class="btn btn-outline" data-action="reset-project">' + icon('trash3') + ' Reset selected project</button><button class="btn btn-danger" data-action="reset-all">Reset all progress</button></div></section></div>' +
      '<section class="panel storage-details"><div class="panel-head"><h2>Data integrity and backup reminders</h2></div><div class="settings-notes"><div><h3>What is saved</h3><p>Task status, completion timestamps, confirmed acceptance criteria, notes, blockers, bookmarks, activity, project repository/deployment records and preferences.</p></div><div><h3>What is never saved</h3><p>Passwords, OAuth client secrets, API keys, provider access tokens, real customer data and payment details. Git and deployment records are manually entered claims.</p></div><div><h3>If data is malformed</h3><p>The tracker pauses writes instead of overwriting unreadable data. Import a validated backup, recover the previous local copy, or reset with explicit confirmation.</p></div><div><h3>Verify a backup</h3><p>Download the JSON, keep it outside this repository, and test importing it in a separate browser profile before relying on it.</p></div></div></section>';
  }

  function renderHandbook() {
    if (!window.LM_HANDBOOK) return '<div class="empty-state"><h3>Handbook could not load</h3><p>Reload the page to restore the engineering handbook module.</p></div>';
    return window.LM_HANDBOOK.render();
  }

  window.LM_PAGES = { renderDashboard, renderProjects, renderProject, renderRoadmap, renderTaskPage, renderProgress, renderSettings, renderHandbook, projectGrid: projectsGrid, activityList };
})();
